// Controlled Unity surface for complete production Shooter+Magazine execution.
// Physics delegates return explicit deterministic contacts; no real PhysX or rendering.
using System;using System.Collections.Generic;using System.Linq;using N=System.Numerics;
namespace UnityEngine {
 public class Object {public string name;public static void Destroy(Object o){}}
 public class Component:Object {public GameObject gameObject;public Transform transform=>gameObject.transform;public T GetComponent<T>() where T:class=>gameObject.parts.OfType<T>().FirstOrDefault();public T GetComponentInParent<T>() where T:class{for(var p=transform;p!=null;p=p.parent){var t=p.GetComponent<T>();if(t!=null)return t;}return null;}}
 public class Behaviour:Component {public bool enabled=true;public bool isActiveAndEnabled=>enabled&&gameObject.activeSelf;}
 public class MonoBehaviour:Behaviour {}public class ScriptableObject:Object{}
 public class GameObject:Object {public bool activeSelf=true;public List<Component> parts=new List<Component>();public Transform transform;public GameObject(string n=""){name=n;transform=new Transform{gameObject=this};parts.Add(transform);}public T AddComponent<T>()where T:Component,new(){var t=new T{gameObject=this};parts.Add(t);return t;}public void SetActive(bool value){activeSelf=value;}}
 public class Transform:Component {public Transform parent;public Vector3 localPosition,localScale=Vector3.one;public Quaternion localRotation=Quaternion.identity;public Vector3 position{get=>parent==null?localPosition:parent.TransformPoint(localPosition);set=>localPosition=parent==null?value:Quaternion.Inverse(parent.rotation)*(value-parent.position);}public Quaternion rotation{get=>parent==null?localRotation:parent.rotation*localRotation;set=>localRotation=parent==null?value:Quaternion.Inverse(parent.rotation)*value;}public Vector3 forward=>rotation*Vector3.forward;public Vector3 TransformPoint(Vector3 p)=>position+rotation*p;public void SetParent(Transform p,bool keepWorld){var pos=position;var rot=rotation;parent=p;if(keepWorld){position=pos;rotation=rot;}}public void SetPositionAndRotation(Vector3 p,Quaternion q){position=p;rotation=q;}public bool IsChildOf(Transform p){for(var x=this;x!=null;x=x.parent)if(x==p)return true;return false;}}
 public struct Vector3 {public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}internal N.Vector3 n=>new N.Vector3(x,y,z);internal static Vector3 V(N.Vector3 p)=>new Vector3(p.X,p.Y,p.Z);public static Vector3 zero=>new Vector3();public static Vector3 one=>new Vector3(1,1,1);public static Vector3 up=>new Vector3(0,1,0);public static Vector3 forward=>new Vector3(0,0,1);public float sqrMagnitude=>x*x+y*y+z*z;public float magnitude=>(float)Math.Sqrt(sqrMagnitude);public Vector3 normalized=>magnitude>1e-8?this/magnitude:zero;public static Vector3 operator+(Vector3 a,Vector3 b)=>V(a.n+b.n);public static Vector3 operator-(Vector3 a,Vector3 b)=>V(a.n-b.n);public static Vector3 operator-(Vector3 a)=>V(-a.n);public static Vector3 operator*(Vector3 a,float f)=>V(a.n*f);public static Vector3 operator/(Vector3 a,float f)=>V(a.n/f);public static float Dot(Vector3 a,Vector3 b)=>N.Vector3.Dot(a.n,b.n);public static Vector3 ProjectOnPlane(Vector3 a,Vector3 n)=>a-n*Dot(a,n);}
 public struct Quaternion{internal N.Quaternion n;public static Quaternion identity=>new Quaternion{n=N.Quaternion.Identity};public static Quaternion Inverse(Quaternion q)=>new Quaternion{n=N.Quaternion.Inverse(q.n)};public static Quaternion operator*(Quaternion a,Quaternion b)=>new Quaternion{n=a.n*b.n};public static Vector3 operator*(Quaternion q,Vector3 v)=>Vector3.V(N.Vector3.Transform(v.n,q.n));public static Quaternion Euler(float x,float y,float z)=>new Quaternion{n=N.Quaternion.CreateFromYawPitchRoll(y*(float)Math.PI/180,x*(float)Math.PI/180,z*(float)Math.PI/180)};public static Quaternion LookRotation(Vector3 d)=>Euler(0,(float)Math.Atan2(d.x,d.z)*180/(float)Math.PI,0);}
 public struct Color{public float r,g,b,a;public Color(float r,float g,float b,float a=1){this.r=r;this.g=g;this.b=b;this.a=a;}}
 public class Shader:Object{public static Shader Find(string name)=>new Shader();}public class Material:Object{public Material(Shader s){}public bool HasProperty(string name)=>false;public void SetColor(string name,Color c){}}public class Mesh:Object{}public class AudioClip:Object{}public class MeshFilter:Component{public Mesh sharedMesh;}public class MeshRenderer:Behaviour{public Material[] sharedMaterials;public Rendering.ShadowCastingMode shadowCastingMode;public bool receiveShadows;public Rendering.LightProbeUsage lightProbeUsage;public Rendering.ReflectionProbeUsage reflectionProbeUsage;}
 public class Collider:Component{public Vector3 ClosestPoint(Vector3 p)=>transform.position;}public class CharacterController:Collider{public Vector3 center=new Vector3(0,1,0);}
 public struct RaycastHit{public Collider collider;public Vector3 point,normal;public float distance;}
 public struct LayerMask{public int value;public static implicit operator int(LayerMask x)=>x.value;public static implicit operator LayerMask(int x)=>new LayerMask{value=x};}public enum QueryTriggerInteraction{Ignore}
 public static class Physics{public static Func<Vector3,Collider[]> Overlap;public static Func<Vector3,Vector3,float,RaycastHit[]> Sweep;public static int OverlapSphereNonAlloc(Vector3 p,float radius,Collider[] output,int mask,QueryTriggerInteraction q){var hits=Overlap?.Invoke(p)??Array.Empty<Collider>();int count=Math.Min(hits.Length,output.Length);Array.Copy(hits,output,count);return count;}public static int SphereCastNonAlloc(Vector3 p,float radius,Vector3 direction,RaycastHit[] output,float distance,int mask,QueryTriggerInteraction q){var hits=Sweep?.Invoke(p,direction,distance)??Array.Empty<RaycastHit>();int count=Math.Min(hits.Length,output.Length);Array.Copy(hits,output,count);return count;}}
 public static class Time{public static float deltaTime=1f/60,timeScale=1;}public static class Application{public static bool isPlaying=true;}public static class Debug{public static void LogWarning(string s,Object context){}public static void LogError(string s,Object context){throw new Exception(s);}}
 public static class Mathf{public static float Min(float a,float b)=>Math.Min(a,b);public static int Min(int a,int b)=>Math.Min(a,b);public static float Max(float a,float b)=>Math.Max(a,b);public static int Clamp(int a,int b,int c)=>Math.Clamp(a,b,c);public static float Clamp(float a,float b,float c)=>Math.Clamp(a,b,c);}
 public static class Gizmos{public static Color color;public static void DrawWireSphere(Vector3 p,float r){}public static void DrawRay(Vector3 p,Vector3 d){}}
 public class DisallowMultipleComponent:Attribute{}public class DefaultExecutionOrder:Attribute{public DefaultExecutionOrder(int i){}}public class HeaderAttribute:Attribute{public HeaderAttribute(string s){}}public class TooltipAttribute:Attribute{public TooltipAttribute(string s){}}public class RangeAttribute:Attribute{public RangeAttribute(float a,float b){}}public class MinAttribute:Attribute{public MinAttribute(float a){}}public class TextAreaAttribute:Attribute{}public class CreateAssetMenuAttribute:Attribute{public string menuName,fileName;}
}
