namespace IntercomMvp {
 public class IntercomWeaponPose:UnityEngine.Behaviour {public bool IsReadyToFire=true;public event Action ShotReady,FireCancelled;public int Recoils;public void EmitShot()=>ShotReady?.Invoke();public void Cancel()=>FireCancelled?.Invoke();public void ConfirmShotVisual(){Recoils++;}}
 public class IntercomWeaponPoseProfile:UnityEngine.ScriptableObject{}
